def max_sum(arr):
    n = len(arr)

    # Step 1: Compute the maximum increasing subsequence sum (left to right)
    inc = arr[:]  # Initialize with the array itself
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and inc[i] < inc[j] + arr[i]:
                inc[i] = inc[j] + arr[i]

    # Step 2: Compute the maximum decreasing subsequence sum (right to left)
    dec = arr[:]  # Initialize with the array itself
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j] and dec[i] < dec[j] + arr[i]:
                dec[i] = dec[j] + arr[i]

    # Step 3: Find the maximum sum of bitonic subsequence
    max_bitonic_sum = 0
    for i in range(n):
        max_bitonic_sum = max(max_bitonic_sum, inc[i] + dec[i] - arr[i])

    return max_bitonic_sum

# Example usage
assert max_sum([1, 15, 51, 45, 33, 100, 12, 18, 9]) == 194
```

