def get_median(arr1, arr2, n):
    """
    Function to find the median of two sorted arrays of the same size.
    :param arr1: First sorted list
    :param arr2: Second sorted list
    :param n: Size of each list
    :return: Median of the two lists
    """
    if n <= 0:
        return -1
    if n == 1:
        return (arr1[0] + arr2[0]) / 2
    if n == 2:
        return (max(arr1[0], arr2[0]) + min(arr1[1], arr2[1])) / 2

    # Calculate medians of the two arrays
    m1 = median(arr1, n)
    m2 = median(arr2, n)

    # If medians are equal, return either
    if m1 == m2:
        return m1

    # If m1 < m2, then the median must be in arr1[m1:] and arr2[:m2]
    if m1 < m2:
        if n % 2 == 0:
            return get_median(arr1[n // 2 - 1:], arr2[:n // 2 + 1], n - n // 2 + 1)
        return get_median(arr1[n // 2:], arr2[:n // 2 + 1], n - n // 2)

    # If m1 > m2, then the median must be in arr1[:m1] and arr2[m2:]
    if n % 2 == 0:
        return get_median(arr2[n // 2 - 1:], arr1[:n // 2 + 1], n - n // 2 + 1)
    return get_median(arr2[n // 2:], arr1[:n // 2 + 1], n - n // 2)


def median(arr, n):
    """
    Helper function to find the median of a sorted array.
    :param arr: Sorted list
    :param n: Size of the list
    :return: Median of the list
    """
    if n % 2 == 0:
        return (arr[n // 2] + arr[n // 2 - 1]) / 2
    return arr[n // 2]
